  auth: {"kind": "bearer", "token": "api_key"},
  credential: [{"name": "api_key", "label": "Access token", "secret": true, "holder": "account"}],
  modes: ["byo_user", "byo_org"],
  timeoutMs: 60000,
  rateLimit: { requests: 25, intervalMs: 1000 },
